const {
  ${1:queryName}: { childImageSharp: {fluid: ${2:imageFluid}}}
} = useStaticQuery(graphql`
  query {
    ${1:queryName}: file(relativePath: { eq: "${3:imagePath.png}" }) {
      childImageSharp {
        fluid(maxWidth: ${4:300}) {
          ...${5|GatsbyImageSharpFluid,GatsbyImageSharpFluid_noBase64,GatsbyImageSharpFluid_tracedSVG,GatsbyImageSharpFluid_withWebp,GatsbyImageSharpFluid_withWebp_noBase64,GatsbyImageSharpFluid_withWebp_tracedSVG|}
        }
      }
    }
  }
`)

